<?php $pageTitle='Programme curriculum';$programmeFilter=(string)($_GET['programme']??'');$semesterFilter=(int)($_GET['semester']??0); ?>
<section class="page-heading"><div><p class="eyebrow">Academic masters</p><h1>Branch-wise subject curriculum</h1><p>Assign every subject code to its programme and teaching semester before examination scheduling.</p></div><div class="heading-actions"><a class="secondary-button" href="<?= e(url('courses/import/template.csv')) ?>">Download template</a><a class="primary-button" href="<?= e(url('courses/import')) ?>">Bulk import subjects</a></div></section>
<?php if($success):?><div class="alert success" role="status"><?= e($success) ?></div><?php endif;?><?php if($error):?><div class="alert error" role="alert"><?= e($error) ?></div><?php endif;?>
<section class="curriculum-stats"><div><span>Curriculum mappings</span><strong><?= number_format(count($courses)) ?></strong></div><div><span>Programmes represented</span><strong><?= number_format(count(array_unique(array_column($courses,'programme_id')))) ?></strong></div><div><span>Subject codes</span><strong><?= number_format(count(array_unique(array_column($courses,'id')))) ?></strong></div></section>
<section class="split-workspace curriculum-workspace"><form class="panel quick-form" method="post" action="<?= e(url('courses')) ?>"><?= csrf_field() ?><p class="eyebrow">New curriculum subject</p><h2>Add subject</h2><label>Programme / branch<select name="programme_id" required><option value="">Select programme</option><?php foreach($programmes as $programme):?><option value="<?= (int)$programme['id'] ?>"><?= e($programme['code'].' - '.$programme['name']) ?></option><?php endforeach;?></select></label><label>Semester<select name="semester" required><option value="">Select semester</option><?php for($i=1;$i<=12;$i++):?><option value="<?= $i ?>">Semester <?= $i ?></option><?php endfor;?></select></label><label>Subject / course code<input name="code" placeholder="CS-101" maxlength="40" required></label><label>Subject name<input name="name" placeholder="Programming Fundamentals" required></label><label>Category<select name="category"><option value="core">Core</option><option value="elective">Elective</option><option value="common">Common</option><option value="bridge">Bridge</option><option value="back_paper">Back paper</option><option value="other">Other</option></select></label><button class="primary-button">Add to curriculum</button></form>
<section class="panel table-panel curriculum-register"><form class="table-toolbar curriculum-filters" method="get"><strong>Curriculum register</strong><select name="programme"><option value="">All programmes</option><?php foreach($programmes as $programme):?><option value="<?= e($programme['code']) ?>" <?= $programmeFilter===$programme['code']?'selected':'' ?>><?= e($programme['code']) ?></option><?php endforeach;?></select><select name="semester"><option value="0">All semesters</option><?php for($i=1;$i<=12;$i++):?><option value="<?= $i ?>" <?= $semesterFilter===$i?'selected':'' ?>>Semester <?= $i ?></option><?php endfor;?></select><button class="secondary-button">Filter</button></form><div class="table-scroll"><table><thead><tr><th>Programme / branch</th><th>Department</th><th>Semester</th><th>Subject code</th><th>Subject name</th><th>Category</th><th>Status</th></tr></thead><tbody><?php $shown=0;foreach($courses as $course):if(($programmeFilter!==''&&$course['programme_code']!==$programmeFilter)||($semesterFilter&&$semesterFilter!==(int)$course['semester']))continue;$shown++;?><tr><td><strong><?= e($course['programme_code']) ?></strong><small class="cell-note"><?= e($course['programme_name']) ?></small></td><td><?= e($course['department_name']?:$course['school_name']) ?></td><td><span class="semester-chip">Semester <?= (int)$course['semester'] ?></span></td><td><strong><?= e($course['code']) ?></strong></td><td><?= e($course['name']) ?></td><td><?= e(ucwords(str_replace('_',' ',$course['category']))) ?></td><td><span class="status-label <?= e($course['status']) ?>"><?= e(ucfirst($course['status'])) ?></span></td></tr><?php endforeach;?><?php if(!$shown):?><tr><td colspan="7" class="empty-table-cell">No subjects match this programme and semester.</td></tr><?php endif;?></tbody></table></div></section></section>
